// Opt-in integration diagnostics; actual media/filesystem and routed WPF commands, not native input.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using Ivad.Ids;
namespace Ivad.Annotator {
 public sealed partial class MainWindow {
  public int IntegrationChecks(string output,string realVideo,bool reopen){
   System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher));
   output=Path.GetFullPath(output);if(!reopen&&Directory.Exists(output)&&Directory.EnumerateFileSystemEntries(output).Any())throw new IOException("Integration checks require a fresh test directory");Directory.CreateDirectory(output);
   var results=new List<object>();var timings=new List<object>();int failed=0;string root=Path.Combine(output,"real-video-project"),full=Path.Combine(output,"full.ids"),receiver=Path.Combine(output,"receiver");
   Action<string,Action> test=(name,action)=>{try{action();results.Add(new{name=name,status="PASS",scope="actual executable/media/filesystem or in-process WPF; not native input"});}catch(Exception e){failed++;results.Add(new{name=name,status="FAIL",error=e.ToString()});}File.WriteAllText(Path.Combine(output,reopen?"reopen-results.json":"results.json"),Codec.Json(new{passed=results.Count-failed,failed=failed,tests=results,timings=timings,executable=System.Reflection.Assembly.GetEntryAssembly().Location}));};
   if(!reopen){
    test("real-video/new-independent-project-import-source-unchanged",()=>{Check(File.Exists(realVideo),"real video exists");string before=Codec.HashFile(realVideo);var s=Store.Create(root,"真实视频隔离回归","本地测试副本");var eq=s.Add("Equipment",new Dictionary<string,object>{{"name","测试设备"},{"project_id",s.Data.project_id}});var cam=s.Add("Camera",new Dictionary<string,object>{{"name","测试摄像头"},{"equipment_id",eq.id}});s.Save();var v=s.ImportVideo(realVideo,cam.id);Use(s);Check(s.Data.entities.All(e=>e.kind!="Frame"),"import does not extract");Check(Codec.HashFile(realVideo)==before&&s.Find(v.Text("camera_id")).id==cam.id,"source hash and association");File.WriteAllText(Path.Combine(output,"real-source-sha256.txt"),before);});
    test("real-video/extract-by-this-executable-background-progress",()=>{string video=store.Data.entities.First(e=>e.kind=="Video").id;Run("真实视频抽帧回归",()=>{ExtractProcess(root,video,new[]{1.0,0,4,4.0});return new Store(root);},Use);AwaitOperation();Check(frames.Items.Count>=2&&frames.Items.Count<=4,"bounded real frames");Check(extractionProgress!=null&&extractionProgress.Contains("抽帧完成"),"worker progress completion");Check(store.Data.entities.Where(e=>e.kind=="Frame").All(e=>e.Number("source_timestamp_100ns")>=0),"PTS preserved");});
    test("real-video/cancel-background-worker-without-source-loss",()=>{string video=store.Data.entities.First(e=>e.kind=="Video").id;string before=Codec.Fingerprint(new Store(root).Data);bool cancelled=false;var clock=Stopwatch.StartNew();Work.Configure(()=>clock.ElapsedMilliseconds>250,null);try{VideoJobs.Run(root,video,new[]{.01,0,Double.MaxValue,5000.0},null);}catch(OperationCanceledException){cancelled=true;}finally{Work.Configure(null,null);}Check(cancelled,"actual child cancellation");Check(before==Codec.Fingerprint(new Store(root).Data),"cancel rolls back and committed data unchanged");});
    test("annotation/box-polygon-roi-and-save-next",()=>{Use(new Store(root));Navigate("标注与审核");var fault=store.Add("Fault",new Dictionary<string,object>{{"name","测试异常类别"},{"taxonomy_version",1}});store.Save();Refresh();frames.SelectedIndex=0;string id=frame.id;store.AddGeometryCurrent(id,fault.id,"box",new[]{1.0,1,20,20},false);store.AddGeometryCurrent(id,fault.id,"polygon",new[]{2.0,2,24,2,24,24},false);store.AddGeometryCurrent(id,"","polygon",new[]{3.0,3,26,3,26,26},true);Refresh();string next=NextVisibleFrame(id);saveAdvanceCommand.Execute(null,this);AwaitOperation();Check(frame.id==next,"save advances");var disk=new Store(root);Check(disk.Find(id).Text("state")=="abnormal"&&disk.Data.entities.Count(e=>e.Text("frame_id")==id&&(e.kind=="Annotation"||e.kind=="ROI"))==3,"geometry persisted");Check(disk.Data.entities.Last(e=>e.kind=="Review"&&e.Text("frame_id")==id).Text("status")=="confirmed","confirmation");});
    test("annotation/empty-normal-and-review-permissions",()=>{string id=frame.id;saveAdvanceCommand.Execute(null,this);AwaitOperation();Check(new Store(root).Find(id).Text("state")=="normal","empty saves normal");Check(review.Visibility==Visibility.Collapsed,"review permissions remain hidden for normal actor");actor.Text="本地管理员";Check(review.Visibility==Visibility.Visible,"admin review shown");actor.Text="本地审核员";});
    test("viewport/zoom-pan-coordinate-roundtrip-and-reset",()=>{var content=(FrameworkElement)Content;content.Measure(new Size(1600,960));content.Arrange(new Rect(0,0,1600,960));content.UpdateLayout();double[] before=store.Data.entities.Where(e=>e.kind=="Annotation").SelectMany(Points).ToArray();ZoomViewport(2);viewportOffset=new Vector(43,-17);ApplyViewport();var q=new Point(25,31);Point host=canvas.TranslatePoint(q,imageHost),back=imageHost.TranslatePoint(host,canvas);Check((q-back).Length<.001&&viewportZoom==2,"transformed input inverts to image coordinates");Check(before.SequenceEqual(store.Data.entities.Where(e=>e.kind=="Annotation").SelectMany(Points)),"view never mutates source geometry");ResetViewport();Check(viewportZoom==1&&viewportOffset.Length==0,"fit reset");});
    test("IDS/full-export-import-idempotence-and-assets",()=>{Packages.Export(store,full,null);var imported=Packages.Import(full,receiver);Rules.VerifyAssets(imported.Data,receiver);Check(Codec.Fingerprint(imported.Data)==Codec.Fingerprint(QueueProjection.Active(store.Data)),"full document equivalent");Check(Codec.Fingerprint(Packages.Import(full,receiver).Data)==Codec.Fingerprint(imported.Data),"full duplicate idempotent");});
    test("IDS/soft-delete-incremental-restore-and-idempotence",()=>{var baseline=Codec.Clone(store.Data);string id=store.Data.entities.First(e=>e.kind=="Frame").id;store.SetQueueDeleted(new[]{id},true,"integration");string deleted=Path.Combine(output,"deleted.ids");Packages.Export(store,deleted,baseline);var got=Packages.Import(deleted,receiver);Check(!got.Data.entities.Any(e=>e.id==id),"deleted frame excluded from effective IDS");baseline=Codec.Clone(store.Data);store.SetQueueDeleted(new[]{id},false,"integration");string restored=Path.Combine(output,"restored.ids");Packages.Export(store,restored,baseline);got=Packages.Import(restored,receiver);Check(got.Find(id).Text("state")=="abnormal"&&got.Data.entities.Any(e=>e.kind=="ROI"&&e.Text("frame_id")==id),"restore geometry and state");string expected=Codec.Fingerprint(got.Data);Check(Codec.Fingerprint(Packages.Import(restored,receiver).Data)==expected,"delta duplicate idempotence");Rules.VerifyAssets(got.Data,receiver);});
    test("IDS/damaged-package-rejected-without-changing-target",()=>{string bad=Path.Combine(output,"corrupt.ids");using(var src=File.OpenRead(full))using(var dst=File.Create(bad)){byte[] bytes=new byte[512];int n=src.Read(bytes,0,bytes.Length);dst.Write(bytes,0,n);}string before=Codec.Fingerprint(new Store(receiver).Data);bool rejected=false;try{Packages.Import(bad,receiver);}catch{rejected=true;}Check(rejected&&before==Codec.Fingerprint(new Store(receiver).Data),"reject and rollback");});
    test("project/save-reopen-expected-state",()=>{Use(new Store(root));Navigate("标注与审核");Rules.VerifyAssets(store.Data,root);File.WriteAllText(Path.Combine(output,"expected-fingerprint.txt"),Codec.Fingerprint(store.Data));Check(store.Data.entities.Any(e=>e.kind=="ROI"),"ROI present");});
    foreach(int count in new[]{1000,10000})test("performance/list-select-update-scroll-"+count,()=>{
     var s=Fixture(Path.Combine(output,"list-"+count),2);var model=s.Data.entities.First(e=>e.kind=="Frame");for(int i=2;i<count;i++){var e=Codec.Parse<Entity>(Codec.Json(model));e.id=Guid.NewGuid().ToString();e.data["pts_us"]=(long)i*100000;e.data["source_timestamp_100ns"]=(long)i*1000000;s.Data.entities.Add(e);}s.Save();Use(s);Navigate("标注与审核");Show();UpdateLayout();var content=(FrameworkElement)Content;content.Measure(new Size(1600,960));content.Arrange(new Rect(0,0,1600,960));content.UpdateLayout();var select=new List<double>();var scroll=new List<double>();var update=new List<double>();Work.ResetMetrics();
     for(int i=0;i<100;i++){frames.ResetSelection();var clock=Stopwatch.StartNew();frames.SelectRange(0,count-1,false);Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));frames.UpdateLayout();select.Add(clock.Elapsed.TotalMilliseconds);Check(frames.Ids.Count==count,"exact selected count");clock.Restart();int targetIndex=i%2==0?count-1:0;frames.ScrollIntoView(frames.Items[targetIndex]);Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));frames.UpdateLayout();Check(frames.ItemContainerGenerator.ContainerFromIndex(targetIndex)!=null,"scrolled target row actually realized");scroll.Add(clock.Elapsed.TotalMilliseconds);clock.Restart();var c=(Choice)frames.Items[i%count];c.Name=c.Name+" *";Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));frames.UpdateLayout();update.Add(clock.Elapsed.TotalMilliseconds);}
     select.Sort();scroll.Sort();update.Sort();Check(Work.HashCalls==0,"no file SHA in selection/update/scroll");int realized=Elements(frames).OfType<ListBoxItem>().Count();Check(realized>0&&realized<100,"bounded realized rows");timings.Add(new{frames=count,samples=100,select_p50_ms=select[49],select_p95_ms=select[94],scroll_p95_ms=scroll[94],update_p95_ms=update[94],realized_rows=realized,scope="in-process WPF selection/layout/scroll; metadata repeats 2 synthetic image assets; NOT physical mouse end-to-end"});Check(select[94]<200&&scroll[94]<200,"scoped UI latency budget");
    });
   }else{
    test("EXE/restart-open-same-project-state-and-export",()=>{Use(new Store(root));Navigate("标注与审核");Check(Codec.Fingerprint(store.Data)==File.ReadAllText(Path.Combine(output,"expected-fingerprint.txt")),"actual new process preserves saved metadata");Check(store.Data.entities.Any(e=>e.kind=="ROI")&&store.Data.entities.Any(e=>e.kind=="Frame"&&e.Text("state")=="abnormal")&&store.Data.entities.Any(e=>e.kind=="Frame"&&e.Text("state")=="normal"),"all states persist");Rules.VerifyAssets(store.Data,root);Packages.Export(store,Path.Combine(output,"after-restart.ids"),null);});
   }
   ticker.Stop();return failed==0?0:1;
  }
 }
}
